from pybricks.hubs import PrimeHub
from pybricks.parameters import Button, Color, Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up all devices.
prime_hub = PrimeHub()
color_sensor = ColorSensor(Port.E)
Left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(Left, Right, 82, 128)

# Initialize variables.
myWhite = 100
myBlack = 0
targetValue = 50
baseSpeed = 400
correction = 25

def CS_Calibration():
    global myWhite, myBlack, targetValue
    # Color Sensor Calibration for LineFollower
    # Place robot color sensor on most white on mat
    prime_hub.light.on(Color.WHITE)
    # Wait until you place sensor on white and press hub center button
    while not Button.RIGHT in prime_hub.buttons.pressed():
        wait(0)
    myWhite = color_sensor.reflection()
    prime_hub.speaker.beep(200, 1000)
    print('myWhite value is: ', myWhite)
    prime_hub.display.number(myWhite)
    while not Button.RIGHT in prime_hub.buttons.pressed():
        wait(0)
    prime_hub.light.on(Color.BLUE)
    # Place robot color sensor on most black on mat
    while not Button.RIGHT in prime_hub.buttons.pressed():
        wait(0)
    # Wait until you place sensor on black and press hub center button
    myBlack = color_sensor.reflection()
    prime_hub.speaker.beep(300, 500)
    print('myBlack value is: ', myBlack)
    prime_hub.display.number(myBlack)
    while not Button.RIGHT in prime_hub.buttons.pressed():
        wait(0)
    # Settarget value for line foller program
    targetValue = (myWhite + myBlack) / 2
    print(targetValue)
    prime_hub.display.number(targetValue)
    while not Button.RIGHT in prime_hub.buttons.pressed():
        wait(0)
    prime_hub.speaker.beep(2000, 2000)


# The main program starts here.
CS_Calibration()
print('End of Program', 'abc')
